        kind: "terminal-fact",
        legId: legCandidate.legId,
        terminalStatus: "missing",
        report: legCandidate.rationale,
        windowRelation: "within",
        evidenceRefs: [...evidenceRefs],
        targetSnapshotHead: targetHead,
      });
    }

